import argparse
import json
import os
import sys
import time
from typing import Dict, List, Optional

def load_config(config_path: str) -> Dict[str, int]:
    with open(config_path, 'r') as f:
        import yaml
        config = yaml.safe_load(f)
    return {node['name']: node['capacity'] for node in config['nodes']}

def load_jobs(jobs_path: str) -> List[str]:
    with open(jobs_path, 'r') as f:
        return json.load(f)

def load_cache(cache_path: str) -> Optional[Dict[str, str]]:
    if os.path.exists(cache_path):
        with open(cache_path, 'rb') as f:
            return json.load(f)
    return None

def save_cache(cache_path: str, mapping: Dict[str, str]) -> None:
    with open(cache_path, 'wb') as f:
        json.dump(mapping, f)

def assign_jobs(config: Dict[str, int], jobs: List[str], cache: Optional[Dict[str, str]], interval_ms: int) -> Dict[str, str]:
    mapping = cache.copy() if cache else {}
    last_assignment_time = 0

    for job in jobs:
        current_time = time.time() * 1000
        if current_time - last_assignment_time < interval_ms:
            continue
        last_assignment_time = current_time

        assigned = False
        for node in config:
            if mapping.get(job) is None and config[node] > mapping.get(node, 0):
                mapping[job] = node
                mapping[node] = mapping.get(node, 0) + 1
                assigned = True
                break

    return mapping

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('config', type=str)
    parser.add_argument('jobs', type=str)
    parser.add_argument('cache', type=str)
    args = parser.parse_args()

    config = load_config(args.config)
    jobs = load_jobs(args.jobs)
    cache = load_cache(args.cache)
    interval_ms = config.get('interval_ms', 200)

    mapping = assign_jobs(config, jobs, cache, interval_ms)
    print(json.dumps(mapping))
    save_cache(args.cache, mapping)

if __name__ == "__main__":
    main()

import sys
import time
from collections import defaultdict

def parse_config(config_file):
    config = {}
    with open(config_file, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line.startswith('interval_ms'):
                config['interval_ms'] = int(line.split()[1])
            elif line.startswith('name'):
                parts = line.split()
                node_name = parts[0]
                node_capacity = int(parts[1])
                config[node_name] = node_capacity
    return config

def parse_jobs(job_file):
    jobs = []
    with open(job_file, 'r') as f:
        for line in f:
            jobs.append(line.strip())
    return jobs

def read_cache(cache_file):
    cache = {}
    if cache_file.exists():
        with open(cache_file, 'r') as f:
            for line in f:
                job_id, node_name = line.strip().split()
                cache[job_id] = node_name
    return cache

def write_cache(cache_file, assignments):
    with open(cache_file, 'w') as f:
        for job_id, node_name in assignments.items():
            f.write(f"{job_id} {node_name}\n")

def assign_jobs(config, jobs, cache):
    node_capacities = {name: config[name] for name in config}
    assignments = cache.copy()

    for job_id in jobs:
        assigned = False
        for node_name in node_capacities:
            if node_capacities[node_name] > 0:
                if job_id not in assignments:
                    assignments[job_id] = node_name
                    node_capacities[node_name] -= 1
                    assigned = True
                    break
        if not assigned:
            break
        time.sleep(config['interval_ms'] / 1000.0)

    return assignments

def main():
    if len(sys.argv) != 4:
        print("Usage: python assign_jobs.py config.txt jobs.txt assignments.cache")
        sys.exit(1)

    config_file = sys.argv[1]
    jobs_file = sys.argv[2]
    cache_file = sys.argv[3]

    config = parse_config(config_file)
    jobs = parse_jobs(jobs_file)
    cache = read_cache(cache_file)

    assignments = assign_jobs(config, jobs, cache)

    for job_id, node_name in assignments.items():
        print(f"{job_id} {node_name}")

    write_cache(cache_file, assignments)

