import time
from collections import defaultdict

def parse_config(config_file):
    interval_ms = None
    nodes = {}
    with open(config_file, 'r') as f:
        for line in f:
            parts = line.strip().split()
            if parts[0] == 'interval_ms':
                interval_ms = int(parts[1])
            else:
                node_name, capacity = parts
                nodes[node_name] = int(capacity)
    return interval_ms, nodes

def parse_jobs(job_file):
    jobs = []
    with open(job_file, 'r') as f:
        for line in f:
            jobs.append(line.strip())
    return jobs

def parse_cache(cache_file):
    assignments = []
    if cache_file and os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            for line in f:
                assignments.append(line.strip())
    return assignments

def assign_jobs(interval_ms, nodes, jobs, assignments):
    node_usage = defaultdict(int)
    for job, node in assignments:
        node_usage[node] += 1

    new_assignments = []
    for job in jobs:
        assigned = False
        for node in nodes:
            if node_usage[node] < nodes[node]:
                node_usage[node] += 1
                new_assignments.append((job, node))
                assigned = True
                break
        if not assigned:
            time.sleep(interval_ms / 1000)
    return assignments + new_assignments

def main():
    if len(sys.argv) != 4:
        print("Usage: python assign_jobs.py config.txt jobs.txt assignments.cache")
        sys.exit(1)

    config_file, job_file, cache_file = sys.argv[1], sys.argv[2], sys.argv[3]
    interval_ms, nodes = parse_config(config_file)
    jobs = parse_jobs(job_file)
    assignments = parse_cache(cache_file)

    new_assignments = assign_jobs(interval_ms, nodes, jobs, assignments)

    with open(cache_file, 'w') as f:
        for job, node in new_assignments:
            f.write(f"{job} {node}\n")

