import sys
import time
from collections import defaultdict

def parse_config(config_file):
    interval_ms = None
    nodes = {}
    with open(config_file, 'r') as f:
        for line in f:
            parts = line.strip().split()
            if parts[0] == 'interval_ms':
                interval_ms = int(parts[1])
            else:
                node_name, capacity = parts
                nodes[node_name] = int(capacity)
    return interval_ms, nodes

def load_cache(cache_file):
    assignments = []
    if cache_file and os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            for line in f:
                assignments.append(line.strip().split())
    return assignments

def save_cache(cache_file, assignments):
    with open(cache_file, 'w') as f:
        for job_id, node_name in assignments:
            f.write(f"{job_id} {node_name}\n")

def assign_jobs(interval_ms, nodes, jobs, cache_assignments):
    assignments = cache_assignments.copy()
    node_usage = defaultdict(int)

    for job_id in jobs:
        if any(job_id == job_id_ for job_id_, _ in assignments):
            continue

        assigned = False
        for node_name in nodes:
            if node_usage[node_name] < nodes[node_name]:
                assignments.append((job_id, node_name))
                node_usage[node_name] += 1
                assigned = True
                break

        if assigned:
            time.sleep(interval_ms / 1000.0)

    return assignments

def main():
    if len(sys.argv) != 4:
        print("Usage: python assign_jobs.py config.txt jobs.txt assignments.cache")
        sys.exit(1)

    config_file, jobs_file, cache_file = sys.argv[1], sys.argv[2], sys.argv[3]
    interval_ms, nodes = parse_config(config_file)
    jobs = [line.strip() for line in open(jobs_file, 'r')]
    cache_assignments = load_cache(cache_file)

    final_assignments = assign_jobs(interval_ms, nodes, jobs, cache_assignments)
    save_cache(cache_file, final_assignments)

    for job_id, node_name in final_assignments:
        print(f"{job_id} {node_name}")

